describe('HoleSceneBuilder sensor presentation', () => {
  it('paints hazards as a thin slab on the surface instead of the collider box', () => {
    const builder = new HoleSceneBuilder();
    const group = builder.build(makeHole()).group;

    const lava = meshNamed(group, 'lava');
    const pond = meshNamed(group, 'pond');
    const flush = 0.25 + HAZARD_SLAB_LIFT + HAZARD_SLAB_HEIGHT / 2;

    expect(lava.scale.y).toBeCloseTo(HAZARD_SLAB_HEIGHT);
    expect(lava.scale.x).toBeCloseTo(2.2);
    expect(lava.scale.z).toBeCloseTo(8);
    expect(lava.position.y).toBeCloseTo(flush);
    expect(lava.position.y - lava.scale.y / 2).toBeGreaterThan(0.25);
    expect(lava.position.y + lava.scale.y / 2).toBeLessThan(0.4);
    expect(lava.position.x).toBeCloseTo(-4);
    expect(lava.position.z).toBeCloseTo(3);
    expect(pond.scale.y).toBeCloseTo(HAZARD_SLAB_HEIGHT);
    expect(pond.position.y).toBeCloseTo(flush);
    builder.dispose();
  });

  it('keeps a hazard over a gap at the top of its own volume', () => {
    const hole = makeHole();
    const builder = new HoleSceneBuilder();

    const pit = meshNamed(builder.build(hole).group, 'pit');

    expect(hazardSurfaceTop(hole, hole.obstacles[2])).toBeCloseTo(-0.5);
    expect(pit.position.y).toBeCloseTo(-0.5 + HAZARD_SLAB_LIFT + HAZARD_SLAB_HEIGHT / 2);
    expect(pit.scale.y).toBeCloseTo(HAZARD_SLAB_HEIGHT);
    builder.dispose();
  });

  it('renders hazards translucent and emissive, casting no shadow', () => {
    const builder = new HoleSceneBuilder();
    const group = builder.build(makeHole()).group;

    const lava = meshNamed(group, 'lava');
    const material = materialOf(group, 'lava');

    expect(material.transparent).toBe(true);
    expect(material.opacity).toBeCloseTo(HAZARD_OPACITY);
    expect(material.depthWrite).toBe(false);
    expect(material.emissiveIntensity).toBeGreaterThan(0);
    expect(material.emissive.getHex()).toBe(0xff5722);
    expect(material.color.getHex()).toBe(0xff5722);
    expect(lava.castShadow).toBe(false);
    expect(lava.receiveShadow).toBe(false);
    builder.dispose();
  });

  it('keeps force field volumes but renders them as a see-through haze', () => {
    const builder = new HoleSceneBuilder();
    const group = builder.build(makeHole()).group;

    const magnet = meshNamed(group, 'magnet');
    const material = materialOf(group, 'magnet');

    expect(magnet.scale.toArray()).toEqual([3, 1.8, 3]);
    expect(magnet.position.y).toBeCloseTo(0.9);
    expect(material.transparent).toBe(true);
    expect(material.opacity).toBeCloseTo(FIELD_OPACITY);
    expect(material.side).toBe(THREE.DoubleSide);
    expect(magnet.castShadow).toBe(false);
    builder.dispose();
  });

  it('leaves solid obstacles opaque and unchanged', () => {
    const builder = new HoleSceneBuilder();
    const hole = makeHole();
    const result = builder.build(hole);

    const wall = meshNamed(result.group, 'wall');
    const material = materialOf(result.group, 'wall');

    expect(result.meshCount).toBe(hole.surfaces.length + hole.obstacles.length + 1);
    expect(wall.scale.toArray()).toEqual([0.5, 1.5, 20]);
    expect(wall.position.y).toBeCloseTo(0.75);
    expect(material.transparent).toBe(false);
    expect(wall.castShadow).toBe(true);
    builder.dispose();
  });

  it('caches one sensor material per obstacle type across builds', () => {
    const builder = new HoleSceneBuilder();
    const first = builder.build(makeHole()).group;
    const second = builder.build(makeHole()).group;

    expect(materialOf(second, 'lava')).toBe(materialOf(first, 'lava'));
    expect(materialOf(first, 'pond')).not.toBe(materialOf(first, 'lava'));
    expect(materialOf(first, 'magnet')).not.toBe(materialOf(first, 'wall'));
    builder.dispose();
  });
});
